    16→package com.google.auto.common;
    17→
    18→import static com.google.auto.common.MoreElements.isAnnotationPresent;
    19→import static com.google.common.base.Preconditions.checkNotNull;
    20→
    21→import com.google.common.base.Equivalence;
    22→import com.google.common.base.Predicate;
    23→import com.google.common.collect.FluentIterable;
    24→import com.google.common.collect.ImmutableSet;
    25→import com.google.common.collect.Maps;
    26→
    27→import java.lang.annotation.Annotation;
    28→import java.util.Arrays;
    29→import java.util.List;
    30→import java.util.Map;
    31→
    32→import javax.lang.model.element.AnnotationMirror;
    33→import javax.lang.model.element.AnnotationValue;
    34→import javax.lang.model.element.Element;
    35→import javax.lang.model.element.ExecutableElement;
    36→import javax.lang.model.type.DeclaredType;
    37→import javax.lang.model.util.ElementFilter;
    38→import javax.lang.model.util.Elements;
    39→
    40→/**
    41→ * A utility class for working with {@link AnnotationMirror} instances.
    42→ *
    43→ * @author Gregory Kick
    44→ */
    45→public final class AnnotationMirrors {
    46→  private static final Equivalence<AnnotationMirror> ANNOTATION_MIRROR_EQUIVALENCE =
    47→      new Equivalence<AnnotationMirror>() {
    48→        @Override
    49→        protected boolean doEquivalent(AnnotationMirror left, AnnotationMirror right) {
    50→          return MoreTypes.equivalence().equivalent(left.getAnnotationType(),
    51→              right.getAnnotationType()) && AnnotationValues.equivalence().pairwise().equivalent(
    52→              getAnnotationValuesWithDefaults(left).values(),
    53→              getAnnotationValuesWithDefaults(right).values());
    54→        }
    55→        @Override
    56→        protected int doHash(AnnotationMirror annotation) {
    57→          DeclaredType type = annotation.getAnnotationType();
    58→          Iterable<AnnotationValue> annotationValues =
    59→              getAnnotationValuesWithDefaults(annotation).values();
    60→          return Arrays.hashCode(new int[] {MoreTypes.equivalence().hash(type),
    61→              AnnotationValues.equivalence().pairwise().hash(annotationValues)});
    62→        }
    63→    };
    64→
    65→  /**
    66→   * Returns an {@link Equivalence} for {@link AnnotationMirror} as some implementations
    67→   * delegate equality tests to {@link Object#equals} whereas the documentation explicitly
    68→   * states that instance/reference equality is not the proper test.
    69→   */
    70→  public static Equivalence<AnnotationMirror> equivalence() {
    71→    return ANNOTATION_MIRROR_EQUIVALENCE;
    72→  }
    73→
    74→  /**
    75→   * Returns the {@link AnnotationMirror}'s map of {@link AnnotationValue} indexed by
    76→   * {@link ExecutableElement}, supplying default values from the annotation if the
    77→   * annotation property has not been set.  This is equivalent to
    78→   * {@link Elements#getElementValuesWithDefaults(AnnotationMirror)} but can be called
    79→   * statically without an {@Elements} instance.
    80→   */
    81→  public static Map<ExecutableElement, AnnotationValue> getAnnotationValuesWithDefaults(
    82→      AnnotationMirror annotation) {
    83→    Map<ExecutableElement, AnnotationValue> values = Maps.newLinkedHashMap();
    84→    Map<? extends ExecutableElement, ? extends AnnotationValue> declaredValues =
    85→        annotation.getElementValues();
    86→    for (ExecutableElement method :
    87→        ElementFilter.methodsIn(annotation.getAnnotationType().asElement().getEnclosedElements())) {
    88→      // Must iterate and put in this order, to ensure consistency in generated code.
    89→      if (declaredValues.containsKey(method)) {
    90→        values.put(method, declaredValues.get(method));
    91→      } else if (method.getDefaultValue() != null) {
    92→        values.put(method, method.getDefaultValue());
    93→      } else {
    94→        throw new IllegalStateException(
    95→            "Unset annotation value without default should never happen: "
    96→            + MoreElements.asType(method.getEnclosingElement()).getQualifiedName()
    97→            + '.' + method.getSimpleName() + "()");
    98→      }
    99→    }
   100→    return values;
   101→  }
   102→
   103→  /**
   104→   * Returns an {@link AnnotationValue} for the named element if such an element was
   105→   * either declared in the usage represented by the provided {@link AnnotationMirror}, or if
   106→   * such an element was defined with a default.
   107→   *
   108→   * @throws IllegalArgumentException if no element is defined with the given elementName.
   109→   */
   110→  public static AnnotationValue getAnnotationValue(
   111→      AnnotationMirror annotationMirror, String elementName) {
   112→    return getAnnotationElementAndValue(annotationMirror, elementName).getValue();
   113→  }
   114→
   115→  /**
   116→   * Returns a {@link ExecutableElement} and its associated {@link AnnotationValue} if such
   117→   * an element was either declared in the usage represented by the provided
   118→   * {@link AnnotationMirror}, or if such an element was defined with a default.
   119→   *
   120→   * @throws IllegalArgumentException if no element is defined with the given elementName.
   121→   */
   122→  public static Map.Entry<ExecutableElement, AnnotationValue> getAnnotationElementAndValue(
   123→      AnnotationMirror annotationMirror, final String elementName) {
   124→    checkNotNull(annotationMirror);
   125→    checkNotNull(elementName);
   126→    for (Map.Entry<ExecutableElement, AnnotationValue> entry :
   127→        getAnnotationValuesWithDefaults(annotationMirror).entrySet()) {
   128→      if (entry.getKey().getSimpleName().contentEquals(elementName)) {
   129→        return entry;
   130→      }
   131→    }
   132→    throw new IllegalArgumentException(String.format("@%s does not define an element %s()",
   133→        MoreElements.asType(annotationMirror.getAnnotationType().asElement()).getQualifiedName(),
   134→        elementName));
   135→  }
   136→
   137→  /**
   138→   * Returns all {@linkplain AnnotationMirror annotations} that are present on the given
   139→   * {@link Element} which are themselves annotated with {@code annotationType}.
   140→   */
   141→  public static ImmutableSet<? extends AnnotationMirror> getAnnotatedAnnotations(Element element,
   142→      final Class<? extends Annotation> annotationType) {
   143→    List<? extends AnnotationMirror> annotations = element.getAnnotationMirrors();
   144→    return FluentIterable.from(annotations)
   145→        .filter(new Predicate<AnnotationMirror>() {
   146→          @Override public boolean apply(AnnotationMirror input) {
   147→            return isAnnotationPresent(input.getAnnotationType().asElement(), annotationType);
   148→          }
   149→        })
   150→        .toSet();
   151→  }
   152→
   153→  private AnnotationMirrors() {}
   154→}
