   411→  /**
   412→   * The unit of processing logic that runs under the guarantee that all elements are complete and
   413→   * well-formed. A step may reject elements that are not ready for processing but may be at a later
   414→   * round.
   415→   */
   416→  public interface ProcessingStep {
   417→    /** The set of annotation types processed by this step. */
   418→    Set<? extends Class<? extends Annotation>> annotations();
   419→
   420→    /**
   421→     * The implementation of processing logic for the step. It is guaranteed that the keys in
   422→     * {@code elementsByAnnotation} will be a subset of the set returned by {@link #annotations()}.
   423→     *
   424→     * @return the elements that this step is unable to process, possibly until a later processing
   425→     *     round. These elements will be passed back to this step at the next round of processing.
   426→     */
   427→    Set<Element> process(SetMultimap<Class<? extends Annotation>, Element> elementsByAnnotation);
   428→  }
