   430→  /**
   431→   * A package or type name.
   432→   *
   433→   * <p>It's unfortunate that we have to track types and packages separately, but since there are
   434→   * two different methods to look them up in {@link Elements}, we end up with a lot of parallel
   435→   * logic. :(
   436→   *
   437→   * <p>Packages declared (and annotated) in {@code package-info.java} are tracked as deferred
   438→   * packages, type elements are tracked directly, and all other elements are tracked via their
   439→   * nearest enclosing type.
   440→   */
   441→  private static final class ElementName {
   442→    private enum Kind {
   443→      PACKAGE_NAME,
   444→      TYPE_NAME,
   445→    }
   446→
   447→    private final Kind kind;
   448→    private final String name;
   449→
   450→    private ElementName(Kind kind, String name) {
   451→      this.kind = checkNotNull(kind);
   452→      this.name = checkNotNull(name);
   453→    }
   454→
   455→    /**
   456→     * An {@link ElementName} for a package.
   457→     */
   458→    static ElementName forPackageName(String packageName) {
   459→      return new ElementName(Kind.PACKAGE_NAME, packageName);
   460→    }
   461→
   462→    /**
   463→     * An {@link ElementName} for a type.
   464→     */
   465→    static ElementName forTypeName(String typeName) {
   466→      return new ElementName(Kind.TYPE_NAME, typeName);
   467→    }
   468→
   469→    /**
   470→     * An {@link ElementName} for an annotated element. If {@code element} is a package, uses the
   471→     * fully qualified name of the package. If it's a type, uses its fully qualified name.
   472→     * Otherwise, uses the fully-qualified name of the nearest enclosing type.
   473→     */
   474→    static ElementName forAnnotatedElement(Element element) {
   475→      return element.getKind() == PACKAGE
   476→          ? ElementName.forPackageName(((PackageElement) element).getQualifiedName().toString())
   477→          : ElementName.forTypeName(getEnclosingType(element).getQualifiedName().toString());
   478→    }
   479→
   480→    /**
   481→     * The fully-qualified name of the element.
   482→     */
   483→    String name() {
   484→      return name;
   485→    }
   486→
   487→    /**
   488→     * The {@link Element} whose fully-qualified name is {@link #name()}. Absent if the relevant
   489→     * method on {@link Elements} returns {@code null}.
   490→     */
   491→    Optional<? extends Element> getElement(Elements elements) {
   492→      return Optional.fromNullable(
   493→          kind == Kind.PACKAGE_NAME
   494→              ? elements.getPackageElement(name)
   495→              : elements.getTypeElement(name));
   496→    }
   497→
   498→    @Override
   499→    public boolean equals(Object object) {
   500→      if (!(object instanceof ElementName)) {
   501→        return false;
   502→      }
   503→
   504→      ElementName that = (ElementName) object;
   505→      return this.kind == that.kind && this.name.equals(that.name);
   506→    }
   507→
   508→    @Override
   509→    public int hashCode() {
   510→      return Objects.hash(kind, name);
   511→    }
   512→  }
   513→}
